[CmdletBinding()]
param(
    [switch]$ForceKeys,
    [switch]$ForceEnvironment
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$repo_root = Split-Path -Parent $PSScriptRoot
$environment_path = Join-Path $repo_root ".env"

& (Join-Path $PSScriptRoot "generate-dev-keys.ps1") `
    -Force:$ForceKeys

if ($ForceEnvironment -or -not (Test-Path -LiteralPath $environment_path))
{
    $password_bytes =
        [System.Security.Cryptography.RandomNumberGenerator]::GetBytes(24)
    $postgres_password = [Convert]::ToHexString($password_bytes)
    $environment = @"
# Generated by scripts/initialize-development.ps1.
# This file is ignored by Git. Never commit production credentials.
POSTGRES_PASSWORD=$postgres_password
NINJAYE_RESERVED2_MD5_0=
NINJAYE_RESERVED50=262144
"@
    [System.IO.File]::WriteAllText(
        $environment_path,
        $environment,
        [System.Text.UTF8Encoding]::new($false))

    if (
        $PSVersionTable.PSEdition -eq "Core" -and
        -not $IsWindows
    )
    {
        [System.IO.File]::SetUnixFileMode(
            $environment_path,
            [System.IO.UnixFileMode]::UserRead -bor
                [System.IO.UnixFileMode]::UserWrite)
    }

    Write-Host "Generated .env with a random PostgreSQL development password."
}
else
{
    Write-Host "Existing .env kept unchanged."
}
